import org.apache.commons.imaging.test.TestResources;
import org.junit.jupiter.api.Test;

public class JpegDecoderTest2 {

    @Test
    public void testDecodeBadFile() {
        final File inputFile = TestResources.resourceToFile("/IMAGING-220/timeout-48eb4251935b4ca8b26d1859ea525c1b42ae0c78.jpeg");
        final ByteSource byteSourceFile = ByteSource.file(inputFile);
        assertThrows(ImagingException.class, () -> new JpegDecoder().decode(byteSourceFile));
    }

    @Test
    public void testDecodeWithTiffRgb() {
        final File inputFile = TestResources.resourceToFile("/IMAGING-220/sample-tiff-rgb.jpeg");
        final ByteSource byteSourceFile = ByteSource.file(inputFile);
        JpegDecoder decoder = new JpegDecoder();
        decoder.setTiffRgb();
        assertDoesNotThrow(() -> decoder.decode(byteSourceFile));
    }

    @Test
    public void testDecodeWithoutTiffRgb() {
        final File inputFile = TestResources.resourceToFile("/IMAGING-220/sample-standard-rgb.jpeg");
        final ByteSource byteSourceFile = ByteSource.file(inputFile);
        JpegDecoder decoder = new JpegDecoder();
        assertDoesNotThrow(() -> decoder.decode(byteSourceFile));
    }

    @Test
    public void testDecodeWithInvalidComponent() {
        final File inputFile = TestResources.resourceToFile("/IMAGING-220/invalid-component.jpeg");
        final ByteSource byteSourceFile = ByteSource.file(inputFile);
        assertThrows(ImagingException.class, () -> new JpegDecoder().decode(byteSourceFile));
    }
}

