+            return new ImageInfo(
+                    formatDetails, 32, new ArrayList<>(), ImageFormats.WEBP,
+                    "webp", height, "image/webp", numberOfImages,
+                    -1, -1, -1, -1,
+                    width, false, hasAlpha, false,
+                    colorType, ImageInfo.CompressionAlgorithm.UNKNOWN
