        IptcBlock block = new IptcBlock(1, blockNameBytes, new byte[]{4, 5, 6});
        assertArrayEquals(blockNameBytes, block.getBlockNameBytes());
        assertNotSame(blockNameBytes, block.getBlockNameBytes());
    }

